INSERT INTO public."pois" ("id", "organizacionId", "nombre", "descripcion", "precioMin", "precioMax", "fechaInicio", "fechaFin", "zonaId", "departamentoId", "regionId", "direccion", "latitud", "longitud", "estadoId", "creadoPorId", "fuente", "imagenPrincipalUrl", "puntuacionPromedio", "cantidadReviews", "website", "telefono", "instagram", "duracionEstimada", "emailContacto") VALUES
('d58eb13b-53f7-4c46-8ebe-e5dac4b7cf4c', NULL, 'Bodega Catena Zapata', 'Fundada en 1902, es famosa por su icónico edificio en forma de pirámide maya y por liderar la revolución del Malbec de altura en Mendoza. Ofrece visitas guiadas exclusivas y catas de sus vinos galardonados internacionalmente.', NULL, NULL, NULL, NULL, NULL, 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Cobos s/n, Agrelo, Luján de Cuyo, Mendoza', -33.1234, -68.8543, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'Seed', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=800&q=80', 0, 0, NULL, NULL, NULL, 120, NULL),
('afccb698-0e69-4afb-a6be-0325995664f3', '3d6894b8-eeb2-4658-9dd9-24df8fc0a704', 'Café Ando', 'Café Ando prueba', 1000, 10000, NULL, NULL, NULL, 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Los Pinos 599', -32.9238, -68.8436, '77129a2b-b2c1-40ea-ad20-385bc4044534', '161b3ce1-3186-49d7-b087-ade36e526855', 'prestador', 'https://pub-e2f6233ffa5c42d499c619bcb2607d32.r2.dev/images/1789431957379-Captura-de-pantalla-2026-09-14-203453.png', 3.2, 10, NULL, '2615436244', NULL, 60, NULL),
('1dacc489-6e25-4ae5-8878-2afe143bda1c', NULL, 'Mirador del Challao', 'Punto panorámico con vista a la precordillera.', 1000, 25000, NULL, NULL, NULL, '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Provincial 52', -32.5311, -69.0154, '77129a2b-b2c1-40ea-ad20-385bc4044534', '44ef4cad-2013-46af-8bab-74875076667b', 'turista', 'https://pub-e2f6233ffa5c42d499c619bcb2607d32.r2.dev/images/1789390971987-E0A3223D-DE59-478A-B8C9-2EF5887C9F37.png', 0, 0, NULL, NULL, NULL, 60, NULL),
('002d5ff5-9d59-4db3-843e-1e204ba2e3c5', NULL, 'Parque General San Martín', 'El Parque General San Martín es el parque urbano más antiguo y principal de la Ciudad de Mendoza. Abarca 307 hectáreas cultivadas y 86 hectáreas en expansión con un total de 393 hectáreas. Cuenta con amplios espacios verdes, el Cerro de la Gloria, el Rosedal, un lago artificial y valiosas obras de arte.', 0, 10000, NULL, NULL, NULL, '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ciudad de Mendoza, Mendoza', -32.8894, -68.8752, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'Seed', 'https://pub-e2f6233ffa5c42d499c619bcb2607d32.r2.dev/images/1789502176170-upload-1789502176041.jpg', 4.67, 6, 'https://mendoza.tur.ar/parque-general-san-martin/', 'N/A', '@parquegeneralsanmartin', 180, NULL),
('9d93fb17-ac07-4717-a6a4-3c5d5f9186e6', NULL, 'Mirador del Valle Malargüe', 'Punto panorámico con vista a la precordillera.', 1000, 10000, NULL, NULL, NULL, '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Provincial 52', -32.5311, -69.0154, '8b484db8-61be-43a9-8329-631348632e7f', '44ef4cad-2013-46af-8bab-74875076667b', 'turista', 'https://example.com/pois/mirador-del-valle-1.jpg', 0, 0, NULL, NULL, NULL, 40, NULL),
('b4b4760f-be49-4539-8c83-4e25c73a5c41', '3d6894b8-eeb2-4658-9dd9-24df8fc0a704', 'Bodega Los Andes', 'Visitas guiadas y degustación de vinos de alta gama en Maipú.', 500, 2000, NULL, NULL, 'c8a4ea9b-bb57-411e-a610-367e5dd23fe7', 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta 60 Km 15, Maipú', -32.9781, -68.7852, '77129a2b-b2c1-40ea-ad20-385bc4044534', '161b3ce1-3186-49d7-b087-ade36e526855', 'prestador', 'https://pub-e2f6233ffa5c42d499c619bcb2607d32.r2.dev/images/1789471958974-upload-1789471958878.jpg', 4.67, 3, 'https://bodegalosandes.com', '+54 9 261 123 4567', '@bodegalosandes', 120, NULL),
('ecf57763-66bb-4735-a6ae-935ea0bf9863', '3d6894b8-eeb2-4658-9dd9-24df8fc0a704', 'Bodega Santa Julia', 'En Bodega Santa Julia somos una gran familia de apasionados por nuestra tierra, nuestras uvas, nuestro vino. Contamos con 400 hectáreas certificadas orgánicas, de allí provienen nuestros vinos certificados
INSERT INTO public."pois" ("id", "organizacionId", "nombre", "descripcion", "precioMin", "precioMax", "fechaInicio", "fechaFin", "zonaId", "departamentoId", "regionId", "direccion", "latitud", "longitud", "estadoId", "creadoPorId", "fuente", "imagenPrincipalUrl", "puntuacionPromedio", "cantidadReviews", "website", "telefono", "instagram", "duracionEstimada", "emailContacto") VALUES
('7bac8701-ab16-4b25-bab6-7e6c1d2d87c6', NULL, 'Fuente y Fonda', 'Bodegón gourmet mendocino recomendado por la Guía Michelin, famoso por sus porciones abundantes para compartir al centro de la mesa (pastel de papas al horno de barro, pastas caseras y carnes braseadas) frente a Plaza Italia.', 18000, 38000, '2026-01-01T03:00:00.000Z', NULL, '1a628bba-29a1-4a39-b9c2-e2db77f4b6be', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Montevideo 675 (frente a Plaza Italia), Ciudad de Mendoza', -32.8931, -68.8505, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80', 4.7, 420, 'https://instagram.com/fuenteyfonda', '+54 261 429-8833', '@fuenteyfonda', 110, NULL),
('d3d71b2f-c798-4052-9705-af274d26a81f', NULL, 'Anna Bistró', 'Clásico bistró franco-argentino en la Quinta Sección que cuenta con un encantador jardín interno con olivos, panadería francesa propia (Brillat Savarin) y una cuidada carta de platos mediterráneos y vinos mendocinos.', 22000, 48000, '2026-01-01T03:00:00.000Z', NULL, 'f39d970b-dc54-49c2-9b5d-21202ec37ed2', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Juan B. Justo 161, Ciudad de Mendoza', -32.8855, -68.8565, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80', 4.7, 465, 'https://annabistro.com.ar', '+54 261 425-1818', '@annabistromza', 120, NULL),
('b6b6dd01-4dfb-459d-929b-cd7544385530', NULL, 'Chachingo Craft Beer - Arístides', 'Taproom insignia en la calle Arístides creado por el reconocido enólogo Alejandro Vigil. Ofrece cervezas artesanales premiadas de Maipú, vinos El Enemigo, hamburguesas gourmet y tapas.', 10000, 26000, '2026-01-01T03:00:00.000Z', NULL, 'f4288b67-5929-4c92-b7d1-fadb5d09c6db', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Arístides Villanueva 383, Ciudad de Mendoza', -32.8921, -68.8558, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1200&q=80', 4.6, 350, 'https://chachingo.com', '+54 261 509-2211', '@chachingocraftbeer', 120, NULL),
('6dbf943a-2a68-47a9-8c61-a98ada8160c7', NULL, 'Heladería Ferruccio Soppelsa (Casa Central)', 'Heladería artesanal centenaria e ícono gastronómico de Mendoza desde 1927, famosa por sus helados de receta italiana y sabores regionales como vino Malbec con frutos rojos, dulce de leche mendocino y pistacho.', 4500, 14000, '2026-01-01T03:00:00.000Z', NULL, '1a628bba-29a1-4a39-b9c2-e2db77f4b6be', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Emilio Civit y Belgrano (Esquina Sarmiento), Ciudad de Mendoza', -32.8892, -68.8515, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1501443762994-82bd5dace89a?auto=format&fit=crop&w=1200&q=80', 4.7, 520, 'https://soppelsa.com.ar', '+54 261 423-3222', '@heladossoppelsa', 45, NULL),
('03df9c45-8dc7-4bfc-a894-90319fa388c0', NULL, 'Bodega Urbana Casa Agostino / La Cava de Rufino', 'Experiencia de degustación y vinoteca en plena avenida señorial Emilio Civit, ideal para realizar catas guiadas de distintas regiones vitivinícolas de Mendoza sin salir de la ciudad.', 15000, 42000, '2026-01-01T03:00:00.000Z', NULL, 'f39d970b-dc54-49c2-9b5d-21202ec37ed2', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Emilio Civit 368, Quinta Sección, Ciudad de Mendoza', -32.8891, -68.8555, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=80', 4.7, 180, 'https://mendoza.tur.ar', '+54 261 425-9900', '@turismomendoza', 90, NULL),
('e80afb34-5708-4f0c-aae4-2ca271231a6d', NULL, 'Reserva Natural Divisadero Largo', 'Área natural protegida de 492 hectáreas a solo 15 minutos del centro de la ciudad. Presenta afloramientos geológicos del período Triásico de más de 200 millones de años, cascadas naturales y senderos de trekking interpretativo.', 2000, 4000, '2026-01-01T03:00:00.000Z', NULL, '8632813a-e116-4a39-9f9a-b551f2cb004b', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Provincial 99 (Circuito Papagayos), Piedemonte de Ciudad de Mendoza', -32.8712, -68.9285, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', 4.8, 395, 'https://www.mendoza.gov.ar/ambiente/', '+54 261 425-2090', '@ambientemendoza', 180, NULL),
('9fa475e7-4335-4dd3-a5e2-137d232e4a7e', NULL, 'Espacio Arizu (Ex Bodega Arizu)', 'Monumento Histórico Nacional y joya del patrimonio industrial vitivinícola de 1888. Sus monumentales naves de ladrillo y cavas subterráneas hoy funcionan como centro cultural, ferial y sede de grandes eventos enogastronómicos.', 0, 10000, '2026-01-01T03:00:00.000Z', NULL, '8fdf0e6e-a4b0-456d-88d7-0e8338e7e7d7', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. San Martín 1600, Godoy Cruz, Mendoza', -32.9145, -68.8438, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=1200&q=80', 4.8, 345, 'https://www.godoycruz.gob.ar', '+54 261 413-3000', '@munigodoycruz', 90, NULL),
('da11ca7b-ba32-4f93-8771-a34dd9cb4b0f', NULL, 'Planta Uno Mercado Gastronómico', 'Complejo gastronómico, cultural y comercial desarrollado en los antiguos talleres metalúrgicos Pescarmona (IMPSA). Reúne más de 25 restaurantes, cafés de especialidad, vinotecas, mercado gourmet y jardines al aire libre.', 8000, 40000, '2026-01-01T03:00:00.000Z', NULL, '8fdf0e6e-a4b0-456d-88d7-0e8338e7e7d7', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ceretti 244, Godoy Cruz, Mendoza', -32.9182, -68.8395, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1533900298318-6b8da08a523e?auto=format&fit=crop&w=1200&q=80', 4.8, 530, 'https://plantauno.com', '+54 261 680-1111', '@plantaunomercado', 120, NULL),
('d2daeb78-fc12-4fbe-88db-4cd5ff6668cb', NULL, 'Bodega Escorihuela Gascón y Restaurante 1884 Francis Mallmann', 'Bodega histórica en funcionamiento más antigua de Godoy Cruz (fundada en 1884 por Miguel Escorihuela Gascón). Alberga toneles gigantes tallados, cancha de bochas entre viñedos y el célebre restaurante de fuegos 1884 de Francis Mallmann.', 35000, 130000, '2026-01-01T03:00:00.000Z', NULL, 'eb4e1b71-0c5e-4839-96ec-861180467ebc', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Belgrano 1188, Godoy Cruz, Mendoza', -32.9212, -68.8492, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=1200&q=80', 4.8, 490, 'https://www.escorihuelagascon.com.ar', '+54 261 424-2282', '@escorihuelagascon', 150, NULL),
('42ec8ca9-e84d-403d-aa35-6871350174b5', NULL, 'Teatro Plaza y Plaza Departamental de Godoy Cruz', 'Centro neurálgico cultural y cívico de Godoy Cruz, conformado por la arbolada Plaza Tomás Godoy Cruz, la Iglesia San Vicente Ferrer de estilo neogótico y el histórico cine-teatro Plaza de 1946.', 0, 12000, '2026-01-01T03:00:00.000Z', NULL, 'eb4e1b71-0c5e-4839-96ec-861180467ebc', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Colón 27 (frente a Plaza Godoy Cruz), Godoy Cruz, Mendoza', -32.9255, -68.8446, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1503095396549-807759245b35?auto=format&fit=crop&w=1200&q=80', 4.7, 360, 'https://www.godoycruz.gob.ar', '+54 261 413-3251', '@teatroplaza.gc', 75, NULL),
('24b367ee-eacc-4631-a353-45b7e5c42dd7', NULL, 'Parque Estación Benegas y Museo Ferroviario', 'Predio verde y ciclovía recreativa emplazada en la antigua estación ferroviaria Gobernador Benegas. Ideal para caminatas, running, ferias de emprendedores y paseos en bicicleta conectando Godoy Cruz con Chacras de Coria.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '3913f430-29c0-4dda-b068-226dd0d75eda', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. del Trabajo y Ruta Panamericana, Godoy Cruz, Mendoza', -32.9428, -68.8542, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=1200&q=80', 4.7, 380, 'https://www.godoycruz.gob.ar', NULL, '@munigodoycruz', 90, NULL),
('104b08fe-3ec4-4d7b-beae-1b949bb40276', NULL, 'Parque San Vicente', 'Gran espacio verde de Godoy Cruz donde se celebra anualmente la tradicional Fiesta Provincial de la Cerveza, equipado con circuitos aeróbicos, juegos infantiles y pistas deportivas.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '8fdf0e6e-a4b0-456d-88d7-0e8338e7e7d7', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Cipolletti e Ing. Huergo, Godoy Cruz, Mendoza', -32.9175, -68.8512, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=1200&q=80', 4.6, 295, 'https://www.godoycruz.gob.ar', NULL, '@munigodoycruz', 75, NULL),
('7fb6b0a9-fc90-429f-b534-c76c502a4212', NULL, 'Palmares Open Mall', 'Centro comercial y polo gastronómico con terrazas al aire libre y vista a la precordillera, cines, restaurantes de primer nivel, bares y tiendas.', 0, 35000, '2026-01-01T03:00:00.000Z', NULL, '3913f430-29c0-4dda-b068-226dd0d75eda', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Panamericana 2650, Godoy Cruz, Mendoza', -32.9531, -68.8582, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80', 4.7, 560, 'https://palmares.com.ar', '+54 261 413-9600', '@palmaresopenmall', 120, NULL),
('419de75f-11eb-4dfd-a06c-7d6b2994eafe', NULL, 'Cristo Rey del Valle (Monumento Cívico de Godoy Cruz)', 'Escultura monumental y paseo parquizado en el ingreso sur a Godoy Cruz, rodeado de senderos peatonales y ciclovías con vistas al piedemonte.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '3913f430-29c0-4dda-b068-226dd0d75eda', 'fc864519-a8f4-4828-925f-3173154620c4', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Rotonda Ruta Panamericana y Corredor del Oeste, Godoy Cruz', -32.9482, -68.8595, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1200&q=80', 4.5, 140, 'https://www.godoycruz.gob.ar', NULL, '@munigodoycruz', 30, NULL),
('e97d3622-1f4e-48be-b764-bc24d48e7c8e', NULL, 'Bodega Los Toneles y Abrasado Restaurante', 'Bodega centenaria declarada Patrimonio Cultural de Mendoza (1922) a solo 5 minutos del centro. Destaca por su arquitectura art déco y por albergar Abrasado, restaurante especializado en carnes maduradas en seco (Dry Aged) recomendado por la Guía Michelin.', 30000, 95000, '2026-01-01T03:00:00.000Z', NULL, '382153e2-c0df-4f16-be45-bf1ec721de58', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Acceso Este 1360 (Lateral Norte), Nueva Ciudad, Guaymallén', -32.8952, -68.8124, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=80', 4.8, 510, 'https://bodegalostoneles.com', '+54 261 431-0403', '@bodegalostoneles', 150, NULL),
('46135a50-129e-49d4-9d1e-beb47d59d106', NULL, 'Espacio Cultural Julio Le Parc', 'El centro cultural más grande del oeste argentino, nombrado en honor al célebre artista cinético mendocino Julio Le Parc. Cuenta con cinco salas de teatro circulares, gran hall de exposiciones con el móvil original de Le Parc y jardines.', 0, 10000, '2026-01-01T03:00:00.000Z', NULL, '382153e2-c0df-4f16-be45-bf1ec721de58', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Mitre y Godoy Cruz, San José, Guaymallén, Mendoza', -32.8888, -68.8185, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1503095396549-807759245b35?auto=format&fit=crop&w=1200&q=80', 4.7, 430, 'https://www.mendoza.gov.ar/cultura/', '+54 261 445-8233', '@culturamendoza', 90, NULL),
('2ef4d8d2-3150-4a46-8553-2f3eb2d3f669', NULL, 'Parque del Acceso Este (Predio de la Virgen)', 'Extenso corredor verde lineal de más de 4 kilómetros con ciclovías, estaciones saludables, pistas de patinaje y el monumento a la Virgen María.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '6759575c-74c8-47c8-a887-8a83c7cf1433', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Lateral Norte y Sur del Acceso Este entre Costanera y Estrada, Guaymallén', -32.9012, -68.8195, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=1200&q=80', 4.6, 320, 'https://www.guaymallen.gob.ar', NULL, '@muniguaymallen', 75, NULL),
('8b9b256d-c3a7-46ee-baf9-9d92981cea97', NULL, 'Parque Unimev', 'Tradicional parque barrial y pulmón verde de Villa Nueva, rodeado de cafeterías, heladerías y senderos arbolados muy concurridos por familias y deportistas.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, 'dc0ee243-4f53-4591-a910-32d2fbac9618', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Houssay y Adolfo Calle, Villa Nueva, Guaymallén', -32.9055, -68.7925, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop&w=1200&q=80', 4.6, 260, 'https://www.guaymallen.gob.ar', NULL, '@muniguaymallen', 60, NULL),
('24a17710-9d73-42e0-8bb0-d0f2e163fc4c', NULL, 'Salas de Arte Libertad y Museo Casa Molina Pico', 'Conjunto patrimonial de Villa Nueva que preserva una de las pocas casonas coloniales anteriores al terremoto de 1861 junto a las salas municipales de artes plásticas y escultura.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, 'dc0ee243-4f53-4591-a910-32d2fbac9618', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Libertad 466, Villa Nueva, Guaymallén, Mendoza', -32.8985, -68.7962, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1554907984-15263bfd63bd?auto=format&fit=crop&w=1200&q=80', 4.5, 155, 'https://www.guaymallen.gob.ar', '+54 261 421-7968', '@muniguaymallen', 60, NULL),
('458506fd-a438-4fe2-b6af-aa607ce325f2', NULL, 'Bröd Bakery (Casa Central - Panadería Artesanal)', 'Cafetería de especialidad y panadería de masa madre ubicada en una casona con patio soleado cerca de Plaza Independencia, ideal para desayunos, brunch y pastelería nórdica-mendocina.', 7500, 19000, '2026-01-01T03:00:00.000Z', NULL, '1a628bba-29a1-4a39-b9c2-e2db77f4b6be', '6ead90ce-2dea-47ef-8a8d-180f78115cc9', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Chile 894, Ciudad de Mendoza', -32.8922, -68.8478, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1200&q=80', 4.7, 440, 'https://brodbakery.com', '+54 261 429-5544', '@brodbakery', 60, NULL),
('c37d6680-0f9d-4e2c-b098-25e1c8eaafe8', NULL, 'Bodega RFM (Roberto Francisco Mendoza) - Cuna del Espumante', 'Bodega familiar y champañera artesanal representativa de Guaymallén, Capital Nacional del Espumante, donde en 1902 el inmigrante alemán Carlos Tomba elaboró el primer espumante argentino bajo método champenoise.', 12000, 28000, '2026-01-01T03:00:00.000Z', NULL, '36ba8c87-4e3a-442d-8010-2252873bcbb9', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Severo del Castillo 4680, Los Corralitos, Guaymallén', -32.9175, -68.7125, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=80', 4.7, 170, 'https://www.guaymallen.gob.ar', '+54 261 482-0512', '@muniguaymallen', 90, NULL),
('c7df0c5f-5466-4d84-bba0-7f62ef0dd677', NULL, 'Nova Market & Paseo Dorrego', 'Paseo gastronómico y comercial en el corazón de Dorrego con cafeterías de especialidad, cervecerías, restaurantes familiares y terrazas.', 7000, 28000, '2026-01-01T03:00:00.000Z', NULL, '6759575c-74c8-47c8-a887-8a83c7cf1433', 'dbc4e4b0-b138-4470-bc4f-293c3bb7d3f8', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Moldes y Rondeau, Dorrego, Guaymallén, Mendoza', -32.9065, -68.8268, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1200&q=80', 4.5, 240, 'https://www.guaymallen.gob.ar', NULL, '@novamarketmza', 90, NULL),
('9782b435-465a-4007-bd9b-a6ffb6ec7407', NULL, 'Campo Histórico El Plumerillo', 'Sitio histórico nacional donde el General José de San Martín instaló el campamento de instrucción y organizó a los más de 5.400 soldados del Ejército de los Andes entre 1816 y enero de 1817 antes de iniciar el Cruce de la Cordillera.', 2000, 4500, '2026-01-01T03:00:00.000Z', NULL, '26201b5c-02ba-4dbf-b75a-0b68ab39210d', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Lisandro Moyano e Independencia, Las Heras, Mendoza', -32.8365, -68.8142, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1554907984-15263bfd63bd?auto=format&fit=crop&w=1200&q=80', 4.8, 475, 'https://lasheras.gob.ar', '+54 261 448-6800', '@lasherasturismo', 90, NULL),
('be6c9e9a-0142-47a5-b70a-d5c9760fdda7', NULL, 'Capilla Histórica El Plumerillo', 'Monumento Histórico Nacional construido por la familia Segura. En su oratorio oraban el General San Martín y sus oficiales durante la preparación del Ejército Libertador.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '26201b5c-02ba-4dbf-b75a-0b68ab39210d', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Pedro Pascual Segura s/n, El Plumerillo, Las Heras', -32.8348, -68.8125, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1554907984-15263bfd63bd?auto=format&fit=crop&w=1200&q=80', 4.6, 185, 'https://lasheras.gob.ar', NULL, '@lasherasturismo', 40, NULL),
('3631e3e0-149d-43be-a239-13b19aaabbf4', NULL, 'Cerro Arco (Senderismo y Parapente)', 'El cerro escuela de trekking más popular del Gran Mendoza (1.668 msnm). Ofrece un ascenso accesible de 4,5 km con vistas panorámicas de toda la metrópoli mendocina y de la precordillera, además de vuelos biplaza en parapente.', 0, 4500, '2026-01-01T03:00:00.000Z', NULL, 'c2bd7297-1634-407a-a33e-e5c1a2cb16ca', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Champagnat s/n, Puerta de la Quebrada, El Challao, Las Heras', -32.8285, -68.9265, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', 4.8, 580, 'https://lasheras.gob.ar', NULL, '@lasherasturismo', 210, NULL),
('a682df2c-9427-4124-8dbc-59dc0bad347b', NULL, 'Santuario Nuestra Señora de Lourdes (El Challao)', 'Imponente templo anfiteatro y gruta al pie de los cerros en El Challao, centro de peregrinación religiosa y mirador natural del piedemonte.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, 'c2bd7297-1634-407a-a33e-e5c1a2cb16ca', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Av. Champagnat s/n, El Challao, Las Heras, Mendoza', -32.8475, -68.8962, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1200&q=80', 4.7, 310, 'https://lasheras.gob.ar', '+54 261 444-1695', '@santuariodelchallao', 45, NULL),
('bc2729e9-00ef-4e44-8cf5-4379e69fd8d7', NULL, 'Reserva Natural y Hotel Histórico Villavicencio', 'Reserva natural privada de 72.000 hectáreas en la precordillera de Las Heras. Destaca por los jardines aterrazados del icónico Hotel Termas de Villavicencio (1940), el Camino de los 365 Caracoles, avistaje de guanacos y cóndores, y el parque de aventura Villavicencio Park.', 8000, 32000, '2026-01-01T03:00:00.000Z', NULL, '637981bb-6538-41f9-9cf3-6d464e903f17', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Provincial 52 Km 50, Las Heras, Mendoza', -32.5262, -69.0135, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', 4.9, 610, 'https://rnvillavicencio.com.ar', '+54 261 499-3010', '@reservavillavicencio', 240, NULL),
('32e6f8e1-dde9-4fb9-a8e5-89369436e98a', NULL, 'Bóvedas Históricas de San Martín en Las Heras (Réplica y Museo)', 'Espacio cultural y museo sanmartiniano en el centro de Las Heras que difunde las rutas del Ejército de los Andes y el patrimonio fundacional del departamento.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, '26201b5c-02ba-4dbf-b75a-0b68ab39210d', 'd50df5ee-e2dc-4c57-91a9-c4983952f23a', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'San Miguel 1457, Las Heras, Mendoza', -32.8512, -68.8265, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1554907984-15263bfd63bd?auto=format&fit=crop&w=1200&q=80', 4.5, 130, 'https://lasheras.gob.ar', '+54 261 448-6800', '@lasherasturismo', 45, NULL),
('c8f4c7f6-e32b-4b0e-bf92-bb6f6d671747', NULL, 'Plaza General Espejo (Plaza de Chacras de Coria)', 'El pintoresco corazón del pueblo de Chacras de Coria, rodeado de callejones arbolados, casonas de adobe, cafés, heladerías, galerías de arte y la tradicional feria dominical de anticuarios y artesanos.', 0, 0, '2026-01-01T03:00:00.000Z', NULL, 'c8a4ea9b-bb57-411e-a610-367e5dd23fe7', 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Italia y Aguinaga, Chacras de Coria, Luján de Cuyo', -32.9845, -68.8768, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1200&q=80', 4.8, 510, 'https://lujandecuyo.gob.ar', NULL, '@lujandecuyomza', 90, NULL),
('169afc9c-ac1b-4454-a15b-f90774af67a3', NULL, 'Bodega Lagarde y Restaurante Fogón / Zonda (Estrella Michelin)', 'Una de las bodegas familiares más antiguas de Mendoza (fundada en 1897), rodeada de viñedos centenarios de Malbec plantados en 1906. Su restaurante Zonda Cocina de Paisaje cuenta con Estrella Michelin y Estrella Verde de sustentabilidad.', 40000, 150000, '2026-01-01T03:00:00.000Z', NULL, '765568eb-b56c-437c-8b90-3087d1f9b2cb', 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'San Martín 1745, Mayor Drummond, Luján de Cuyo, Mendoza', -33.0052, -68.8685, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1560493676-04071c5f467b?auto=format&fit=crop&w=1200&q=80', 4.9, 540, 'https://www.lagarde.com.ar', '+54 261 498-0011', '@lagardewine', 180, NULL),
('2758b7d0-868d-44d7-9ef9-9d258cd42ee8', NULL, 'Bodega Norton', 'Fundada en 1895 al pie de la Cordillera de los Andes y propiedad de la familia Swarovski. Famosa por sus jardines panorámicos, su restaurante La Vid con terraza frente al Cordón del Plata y experiencias como "Enólogo por un día".', 30000, 110000, '2026-01-01T03:00:00.000Z', NULL, 'bdd186aa-c872-48ad-9ec2-ee0015904491', 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Provincial 15 Km 23.5, Perdriel, Luján de Cuyo, Mendoza', -33.0815, -68.8942, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?auto=format&fit=crop&w=1200&q=80', 4.8, 525, 'https://www.norton.com.ar', '+54 261 490-9700', '@bodeganorton', 150, NULL),
('4161948c-01b4-4a0f-8527-f5d036bda0c1', NULL, 'Bodega Chandon Argentina', 'Primera filial de Moët & Chandon fuera de Francia, fundada en 1959 en Agrelo. Ofrece recorridos sensoriales exclusivos dedicados al arte de los espumantes de altura y bistró entre jardines.', 35000, 115000, '2026-01-01T03:00:00.000Z', NULL, 'bdd186aa-c872-48ad-9ec2-ee0015904491', 'ea37ec6b-4bcf-4e60-a187-f046cf6995cb', '0c47c372-d70b-4d25-aa7d-fba6f26666e4', 'Ruta Nacional 40 Km 29, Agrelo, Luján de Cuyo, Mendoza', -33.1065, -68.8995, '77129a2b-b2c1-40ea-ad20-385bc4044534', NULL, 'admin', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=1200&q=80', 4.9, 460, 'https://www.chandon.com.ar', '+54 261 490-9968', '@chandon_ar', 150, NULL),
